interface Person {
  name: string;
  age: number;
}

const p: Person = {
  name: "Alice",
  age: 18
}

interface Person {
  name: string;
  age: number;
  gender: string;
}

const p1: Person = {
  name: "Alice",
  age: 18,
  // 可以包含这个属性
  gender: "female"
}

const p2: Person = {
  name: "Bob",
  age: 18,
  // 也可以不包含
}

// 先判断在使用
if (p1.gender) {
  console.log(p1.gender);
}

// 使用可选链
console.log(p1?.gender);

// 我们知道其一定有值，可以断言为非空
console.log(p1.gender!);

interface Person {
  readonly name: string;
  age: number;
}

const p: Person = {
  name: "Alice",
  age: 18
}

// name 不能被修改
// p.name = "Bob"

// age 可以被修改
p.age = 20;
